gene-egfr-interactions.json.body:
{"query": "query($genes: [String!]!) {
  genes(names: $genes) {
    nodes {
      name
      interactions {
        interactionScore
        interactionTypes { type directionality }
        drug { name conceptId }
        interactionAttributes { name value }
        publications { pmid }
        sources { sourceDbName }
      }
    }
  }
}", "variables": {"genes": ["EGFR"]}}
